49	// The volume an override is on ("bracket.stl / Mounting tabs" names the
50	// modifier), or nothing for the object itself.
51	function volumeName(local: CatalogOverrideInfo): string | undefined {
52	  const separator = local.target.indexOf(' / ');
53	  return separator < 0 ? undefined : local.target.slice(separator + 3);
54	}
