62	// A saved chat's table, from the summary the chat saved: the settings that
63	// differed from the presets then, and the objects' own settings. The rest of
64	// the table was not saved, so the panel shows these as the changed ones.
65	export function catalogFromContext(context: WorkspaceContext): SettingsCatalogPayload {
66	  // "0.2 → 0.28 mm" says the unit once; each side gets it back.
67	  const split = (display: string): [string, string] => {
68	    const arrow = display.indexOf(' → ');
69	    if (arrow < 0) return [display, display];
70	    const before = display.slice(0, arrow);
71	    const after = display.slice(arrow + 3);
72	    const unit = after.match(/^-?[\d.,]+ (\D\S*)$/);
73	    return [unit && /^-?[\d.,]+$/.test(before) ? `${before} ${unit[1]}` : before, after];
74	  };
75	  const rows = (type: string): CatalogSettingInfo[] => context.presetDeltas
76	    .filter((delta) => (delta.presetType ?? 'process') === type)
77	    .map((delta) => {
78	      const [presetDisplay, display] = delta.display ? split(delta.display) : [delta.preset, delta.value];
79	      return { key: delta.key, label: delta.label || delta.key, page: delta.page ?? '', group: delta.group ?? '',
80	        value: delta.value, display, preset: delta.preset, presetDisplay };
81	    });
82	  const identity = context.setupIdentity;
83	  const plate = context.plates.find((item) => item.active);
84	  const applied = context.appliedSetup;
85	  return {
86	    available: true,
87	    process: { name: context.printer.process, settings: rows('process') },
88	    printer: { name: identity?.printer ?? context.printer.preset, settings: rows('printer') },
89	    filaments: (identity?.filaments ?? []).map((filament, index) => ({ slot: index + 1, preset: filament.preset,
90	      material: filament.material, colour: '', settings: index === 0 ? rows('filament') : [] })),
91	    plates: plate ? [{ id: plate.id, name: plate.name, active: true, bedType: identity?.plateType ?? '', ownBedType: false,
92	      bedTempKey: '', bedTempInitialKey: '', own: [] }] : [],
93	    objects: (applied?.objects ?? []).map((name, index) => ({
94	      id: plate?.objects.find((item) => item.name === name)?.id ?? `saved-${index}`, name, plateId: plate?.id,
95	      overrides: (applied?.localOverrides ?? []).filter((local) => local.object === index)
96	        .map(({ target, kind, key, value, label, display }) => ({ target, kind, key, value, label, display })) })),
97	  };
98	}
