109	// Consecutive runs that share a heading, in the order they first appear.
110	function runs<T>(items: T[], heading: (item: T) => string): [string, T[]][] {
111	  const groups = new Map<string, T[]>();
112	  for (const item of items) groups.set(heading(item), [...(groups.get(heading(item)) ?? []), item]);
113	  return [...groups];
114	}
