120	function Row({ label, value, bold, muted, notes, tag }: {
121	  label: string; value: string; bold?: boolean; muted?: boolean; notes?: string[]; tag?: string;
122	}) {
123	  return <div className={bold ? 'all-settings-row all-settings-row--changed' : 'all-settings-row'}>
