155	// Rows of one preset under their Orca groups, as a name and a value; a
156	// changed value is bold with the preset's under it.
157	function PresetRows({ settings, notes, byPage }: {
158	  settings: CatalogSettingInfo[]; notes?: (setting: CatalogSettingInfo) => string[]; byPage?: boolean;
159	}) {
