177	// The filament rows, with the bed temperature named for the plate type the
178	// shown plate prints with.
179	function filamentRows(filament: CatalogFilamentInfo, plate: CatalogPlateInfo | undefined, query: string,
180	  filter: SettingsFilter): CatalogSettingInfo[] {
181	  return filament.settings.filter((setting) => matches(setting, query) && (filter === 'all' || changed(setting)))
182	    .map((setting) => plate?.bedType && (setting.key === plate.bedTempKey || setting.key === plate.bedTempInitialKey)
