186	// Two or three slots side by side: one column per slot, the rows being slot
187	// 1's settings in order. A value inherited from the printer reads "printer";
188	// a filament's own override, or a change from its preset, is bold with a
189	// note under the row.
190	function FilamentColumns({ filaments, plate, query, filter }: {
191	  filaments: CatalogFilamentInfo[]; plate?: CatalogPlateInfo; query: string; filter: SettingsFilter;
192	}) {
193	  const perSlot = filaments.map((filament) => new Map(filament.settings.map((setting) => [setting.key, setting])));
194	  const lead = filamentRows(filaments[0], plate, query, 'all');
195	  // The changed filter keeps a row some slot changed from its preset, or
196	  // sets itself where another slot leaves it to the printer.
197	  const shown = filter === 'all' ? lead : lead.filter((row) => perSlot.some((slot) => {
198	    const cell = slot.get(row.key);
199	    return !!cell && (changed(cell) || overridesPrinter(cell, perSlot, row.key));
200	  }));
201	  return <div className="all-settings-columns" style={{ '--all-settings-slots': filaments.length } as React.CSSProperties}>
202	    <div className="all-settings-columns-head">
203	      <span />
204	      {filaments.map((filament) => <span className="all-settings-column-slot" key={filament.slot}>
205	        <Swatch colour={filament.colour} label={`Slot ${filament.slot} · ${shortPreset(filament.preset)}`} />
206	        <span className="all-settings-column-slot-name">Slot {filament.slot}</span>
207	        <span className="all-settings-column-slot-material">{filament.material || shortPreset(filament.preset)}</span>
208	      </span>)}
209	    </div>
210	    {runs(shown, (setting) => [setting.page, setting.group].filter(Boolean).join(' · ')).map(([heading, group]) =>
211	      <div className="all-settings-run" key={heading || '(ungrouped)'}>
212	        {heading && <p className="all-settings-run-name">{heading}</p>}
213	        {group.map((lead) => {
214	          const cells = perSlot.map((slot) => slot.get(lead.key));
215	          const notes = cells.flatMap((cell, index) => {
216	            if (!cell) return [];
217	            const slot = filaments[index].slot;
218	            const lines: string[] = [];
219	            if (changed(cell)) lines.push(`Slot ${slot} preset: ${cell.presetDisplay ?? cell.preset}`);
220	            if (overridesPrinter(cell, perSlot, lead.key))
