222	            return lines;
223	          });
224	          const anyBold = cells.some((cell) => cell && (changed(cell) || overridesPrinter(cell, perSlot, lead.key)));
225	          return <div className={anyBold ? 'all-settings-row all-settings-row--changed' : 'all-settings-row'} key={lead.key}>
226	            <div className="all-settings-row-line all-settings-row-line--columns">
227	              <span className="all-settings-row-name" title={lead.label}>{lead.label}</span>
228	              {cells.map((cell, index) => <span key={index} className={['all-settings-row-value',
229	                cell && (changed(cell) || overridesPrinter(cell, perSlot, lead.key)) && 'all-settings-row-value--bold',
