396	  // "in 4 regions: 2 mounting tabs and 2 screw holes" -- the volumes an
397	  // object prints differently, counted by name.
398	  const regionsOf = (object: CatalogObjectInfo): string => {
399	    const names = runs(object.overrides.filter((local) => volumeName(local)), (local) => volumeName(local)!)
400	      .map(([name, locals]) => locals.length > 1 ? `${locals.length} ${name}` : name);
401	    const regions = object.overrides.filter((local) => volumeName(local)).length;
402	    return regions === 0 ? '' : ` in ${plural(regions, 'region', 'regions')}: ${names.join(' and ')}`;
403	  };
404	
405	  const objectBody = (object: CatalogObjectInfo) => {
406	    type Entry = { key: string; label: string; value: string; tag: string; note: string; page: string };
407	    const processRow = (key: string) => catalog!.process.settings.find((setting) => setting.key === key);
408	    const tagOf = (kind: string) => kind === 'object' ? 'Object' : kind === 'height range' ? 'Height range' : 'Region';
409	    const entries: Entry[] = [];
410	    // Two modifiers of one name that set one setting the same way are one
411	    // row: "Mounting tabs · 2 regions".
412	    const valued = runs(object.overrides.filter((item) => item.key),
413	      (item) => [item.kind, item.key, item.value, volumeName(item) ?? ''].join('\u0000'));
414	    for (const [, locals] of valued) {
415	      const local = locals[0];
416	      const row = processRow(local.key);
417	      const where = volumeName(local) ?? (local.kind === 'object' ? 'Whole object' : sentence(local.kind));
418	      const regions = locals.length > 1 ? ` · ${plural(locals.length, 'region', 'regions')}` : '';
419	      // OrcaSlicer stores an object's filament as a slot number, the one
420	      // setting the panel knows by its key: the slot's preset says more.
421	      const slotNumber = local.key === 'extruder' ? Number(local.value) : NaN;
422	      const filament = Number.isInteger(slotNumber) ? catalog!.filaments.find((item) => item.slot === slotNumber) : undefined;
423	      const projectValue = local.key === 'extruder'
424	        ? catalog!.filaments[0] ? `1 · ${shortPreset(catalog!.filaments[0].preset)}` : '1' : row?.display ?? 'preset';
425	      entries.push({ key: `${local.target}:${local.key}`, label: local.label || sentence(local.key),
426	        value: filament ? `${slotNumber} · ${shortPreset(filament.preset)}` : local.display || local.value, tag: tagOf(local.kind),
427	        note: `${where}${regions} · project: ${projectValue}`,
428	        page: local.key === 'extruder' ? 'Filament' : row ? pageOf(row) : 'Others' });
429	    }
430	    for (const [kind, locals] of runs(object.overrides.filter((item) => !item.key), (item) => item.kind)) {
431	      const names = locals.map((local) => volumeName(local) ?? object.name);
432	      entries.push({ key: kind, label: locals.length > 1 && /blocker|enforcer|part$/.test(kind) ? `${sentence(kind)}s` : sentence(kind),
433	        value: 'On', tag: /blocker|enforcer|part$/.test(kind) ? 'Region' : 'Object',
434	        note: `${names.join(', ')}${locals.length > 1 ? ` · ${plural(locals.length, 'region', 'regions')}` : ''}`,
435	        page: kind.includes('support') ? 'Support' : 'Others' });
436	    }
437	    const shown = entries.filter((entry) => matches(entry, query));
438	    const byPage = new Map(runs(shown, (entry) => entry.page));
439	    const pages = [...PROCESS_PAGES, 'Filament', 'Printer'];
440	    return <>
441	      <div className="all-settings-presets" role="note">
442	        <p className="all-settings-object-summary">{object.overrides.length === 0
443	          ? `${object.name} uses the project’s settings and sets nothing of its own.`
444	          : `${object.name} uses the project’s settings, except${regionsOf(object) || ` for ${plural(object.overrides.length, 'setting', 'settings')} of its own`}.`}</p>
445	      </div>
446	      <div className="all-settings-groups">
447	        {pages.map((page) => {
448	          const rows = byPage.get(page) ?? [];
449	          if (rows.length === 0 && query.trim()) return null;
450	          return <Group key={page} name={page} count={rows.length} summary={rows.length > 0 ? plural(rows.length, 'own setting', 'own settings') : 'same as project'}
451	            open={isOpen(`object:${page}`, true)} onToggle={() => toggle(`object:${page}`, true)}>
452	            {rows.map((entry) => <Row key={entry.key} label={entry.label} value={entry.value} tag={entry.tag} notes={[entry.note]} />)}
453	          </Group>;
454	        })}
455	      </div>
456	    </>;
457	  };
