478	              <span className="all-settings-row-value all-settings-row-value--muted">{object.overrides.length > 0
479	                ? plural(object.overrides.length, 'own setting', 'own settings') : 'same as project'}</span>
480	            </div>
481	          </div>)}
482	        </Group>
483	      </div>
484	    </>;
485	  };
