490	      <ActionMenu label="Showing" appearance="select" text={shownName} items={options} />
491	    </div>
492	    <p className="all-settings-hint">{saved ? 'A saved chat’s setup: the settings that differed from the presets when it was saved.'
493	      : scope.kind === 'object' ? `Follows the selection in the 3D view. Shown: only what ${shownName} sets itself.`
494	      : scope.kind === 'plate' ? `Follows the selection in the 3D view. Shown: what ${shownName} sets itself, and its objects.`
495	      : 'Follows the selection in the 3D view.'}</p>
496	    <div className="all-settings-find">
497	      <label className="field-search all-settings-search">
498	        <span className="jp-icon jp-icon-search" aria-hidden="true" />
499	        <input type="search" placeholder="Search settings" aria-label="Search settings" value={query}
500	          onChange={(event) => setQuery(event.target.value)} />
501	      </label>
502	      <div className="jp-segmented all-settings-filter" role="radiogroup" aria-label="Which settings">
503	        {(['all', 'changed'] as const).map((choice) => <button type="button" key={choice} role="radio"
504	          aria-checked={filter === choice} disabled={saved && choice === 'all'}
505	          className={filter === choice ? 'jp-segment selected' : 'jp-segment'} onClick={() => setFilter(choice)}>
506	          {choice === 'all' ? 'All' : 'Changed'}</button>)}
507	      </div>
508	    </div>
509	    {body()}
510	  </main>;
