struct AppliedSetup
{
    PlateId plate;
    std::size_t printable_objects{0};
    bool spiral_mode{false};
    bool variable_layer_height{false};
    // Names of the objects with a printable copy on the plate, in model order.
    std::vector<std::string> objects;
    std::vector<SetupLocalOverride> local_overrides;
};

enum class SelectionStatus : std::uint8_t { None, Objects, Unsupported };

// Compact project and machine setup facts for consumers (the Agent context)
// that must describe the workspace without reaching into Orca types. Values
// are read fresh from their authoritative owners at snapshot time.
struct WorkspaceSetup
{
    std::string project_name;
    bool        project_dirty{false};
    std::size_t open_edges{0};
    std::size_t repaired_errors{0};

    bool any() const { return open_edges != 0 || repaired_errors != 0; }
    friend bool operator==(const MeshProblem& lhs, const MeshProblem& rhs)
    {
        return lhs.open_edges == rhs.open_edges && lhs.repaired_errors == rhs.repaired_errors;
    }
};

// What the person chose to do to an object beyond placing it. Each flag is
// read from the Orca state that owns it; none is inferred from a label.
struct ObjectCustomization
{
    bool support_painting{false};
    bool seam_painting{false};
    bool color_painting{false};
    bool fuzzy_skin_painting{false};
    bool variable_layer_height{false};
    // Per-object setting overrides in Orca's ModelConfig.
    std::size_t setting_overrides{0};

    // Whether an OrcaSlicer tool made this customization, as opposed to per-object
    // settings, which the shell has no tool to open.
    bool has_tool() const
    {
        return support_painting || seam_painting || color_painting || fuzzy_skin_painting || variable_layer_height;
    }

    bool any() const
    {
        return support_painting || seam_painting || color_painting || fuzzy_skin_painting || variable_layer_height ||
               setting_overrides != 0;
    }
    friend bool operator==(const ObjectCustomization& lhs, const ObjectCustomization& rhs)
    {
        return lhs.support_painting == rhs.support_painting && lhs.seam_painting == rhs.seam_painting &&
               lhs.color_painting == rhs.color_painting && lhs.fuzzy_skin_painting == rhs.fuzzy_skin_painting &&
               lhs.variable_layer_height == rhs.variable_layer_height && lhs.setting_overrides == rhs.setting_overrides;
    }
};

struct OutlineVolume
{
    VolumeId    id;
    std::string name;
    VolumeRole  role{VolumeRole::Part};
    MeshProblem mesh;
    // The volume's own filament override, 1-based as Orca stores it.
    std::optional<int> extruder;
};
    // printer's value is in force; `inherited_display` is that value.
    bool        inherited{false};
    std::string inherited_display;
};

struct CatalogPreset
{
    std::string                 name;
    std::vector<CatalogSetting> settings;
};

struct CatalogFilament
{
    std::size_t                 slot{1}; // 1-based, as a person reads it
    std::string                 preset;
    std::string                 material;
    std::string                 colour; // "#RRGGBB", empty when the project names none
    std::vector<CatalogSetting> settings;
};

struct CatalogPlate
{
    PlateId                     id;
    std::string                 name;
    bool                        active{false};
    std::string                 bed_type;     // the plate type it prints with: its own, else the project's
    bool                        own_bed_type{false};
    // The filament keys that hold the bed temperature for that plate type,
    // for the first layer and the layers after it.
    std::string                 bed_temp_initial_key;
    std::string                 bed_temp_key;
    std::vector<CatalogSetting> own; // the settings the plate sets itself
};

struct CatalogObject
{
    ObjectId                        id;
    std::string                     name;
    std::optional<PlateId>          plate; // the plate a printable copy sits on, when one does
    std::vector<SetupLocalOverride> overrides; // `object` is unused here
};

struct SettingsCatalog
{
    bool                         available{false}; // false for a non-FFF printer
    CatalogPreset                process;
    CatalogPreset                printer;
    std::vector<CatalogFilament> filaments;
    std::vector<CatalogPlate>    plates;
    std::vector<CatalogObject>   objects;
};

class IWorkspace
{
public:
    virtual ~IWorkspace() = default;

    // The production implementation must be called and observed synchronously
    // on the GUI thread. It never mutates Orca from a background thread. Each
    // successful logical change advances revision before its single callback;
    // snapshot() in that callback reports the same revision. The fake is plain
    // C++ and has no GUI-thread restriction.
    virtual WorkspaceSnapshot snapshot() const                                  = 0;
    virtual CommandResult select_object(ObjectId id)                            = 0;
    virtual CommandResult rename_object(ObjectId id, const std::string& name)   = 0;
    virtual CommandResult duplicate_object(ObjectId id)                         = 0;
    virtual CommandResult remove_object(ObjectId id)                            = 0;
    virtual CommandResult undo()                                                = 0;
    virtual CommandResult redo()                                                = 0;

    // Starts Orca's own slicing run: one plate, or every plate when no plate
    // is named. It returns once the run has started, not when it finishes --
    // the result arrives as a Plates change and is read from the snapshot, the
    // way the GUI's own Slice button behaves.
    //
    // Refuses with UnavailableOperation when a slice is already running unless
    // preempt is set, because nothing in Orca records who started a run: a
    // slice in flight may be the person's, and taking it over is a decision
    // the caller must make deliberately rather than by racing.
    virtual CommandResult lay_out(const LayoutRequest& request, const std::string& job_handle, LayoutResult& result) = 0;
    virtual CommandResult place_object(ObjectId id, const PlacementRequest& request, const std::string& job_handle,
                                       PlacementResult& result) = 0;
    virtual CommandResult analyze_object(ObjectId id, const AnalysisRequest& request, ObjectAnalysis& result) const = 0;
    virtual std::vector<ObjectDetails> object_details() const = 0;

    // The Plates pane's read model and the commands that move its selection.
    // `outline` is read fresh from Orca on every call, like snapshot().
    // `select_plate` makes a plate the active one, as clicking it in Orca's own
    // plate list does; `add_plate` is the toolbar's Add plate, one undo step.
    // `select_copy` and `select_volume` select exactly that item, and fail with
    // UnavailableOperation when Orca cannot select at that granularity (a
    // volume of an object with a single model part, or a copy that no plate
    // holds). A no-op selection fails with NoChange.
    virtual ProjectOutline outline() const                       = 0;
    virtual CommandResult  select_plate(PlateId id)              = 0;
    virtual CommandResult  add_plate()                           = 0;
    virtual CommandResult  select_copy(InstanceId id)            = 0;
    virtual CommandResult  select_volume(VolumeId id)            = 0;
    // The plate actions that apply to this plate right now, in menu order:
    // Orca offers Delete only while another plate remains, Move to front only
    // below the first plate, and Filament grouping only on a dual-extruder
    // Bambu printer. `run_plate_action` refuses one that is not in that list
    // with UnavailableOperation instead of running it anyway.
    virtual std::vector<PlateAction> plate_actions(PlateId id) const                       = 0;
    virtual CommandResult            run_plate_action(PlateId id, PlateAction action)      = 0;
    // The object actions that apply to this object now, in menu order: Filament
    // only in a multi-material job, Repair only for a mesh with problems, Split
    // only for an object that has more than one piece. `slot` is the 1-based
    // filament for Filament and ignored otherwise. A refusal by OrcaSlicer comes
    // back as UnavailableOperation.
    virtual std::vector<ObjectAction> object_actions(ObjectId id) const                                    = 0;
    virtual CommandResult             run_object_action(ObjectId id, ObjectAction action, int slot = 0)    = 0;
    // The object list's printable switch for one copy.
    virtual CommandResult             toggle_copy_printable(InstanceId id)                                 = 0;
    // Selects the object and opens the tool on it. `UnavailableOperation` when
    // OrcaSlicer won't open it (a gizmo already running, for one).
    virtual CommandResult             open_customization(ObjectId id, CustomizationTool tool)             = 0;
    virtual ConfiguredPrinter configured_printer() const = 0;
    virtual std::string current_process_preset() const = 0;
    // Read-only: evaluates compatibility without selecting, and leaves every
    // preset and the revision as they were.
    virtual PrinterSetupPreview preview_printer_setup(const PrinterSetupRequest& request) const = 0;
    // Applies in Orca's order -- printer, plate, process, filaments -- and
    // reads the result back into `applied`, substitutions included.
    virtual CommandResult apply_printer_setup(const PrinterSetupRequest& request, PrinterSetupPreview& applied) = 0;
    virtual CommandResult start_slice(std::optional<PlateId> plate, bool preempt) = 0;

    // What one plate's current slice says about itself. Returns a report whose
    // `valid` is false when the plate holds no current slice, rather than
    // failing: "not sliced yet" is an answer, not an error.
    virtual SliceReport slice_report(PlateId plate, const SliceReportRequest& request = {}) const = 0;

    // A page of presets of one kind, as Orca has them. Read-only in the strict
    // sense: it reports Orca's cached compatibility verdict and never asks for
    // a fresh one, because asking writes to preset configs and can move the
    // selection.
    virtual PresetListResult list_presets(const PresetQuery& query) const = 0;

    // Every physical printer the application knows, reachable or not. A
    // printer it has not heard from is a real answer to "what printers do I
    // have", which is not the same question setup asks.
    virtual std::vector<PrinterDevice> printers() const = 0;
    virtual SettingsSearchResult search_settings(const SettingsQuery& query) const = 0;
    virtual SettingsReadResult read_settings(const std::vector<std::string>& keys, const SettingsTarget& target = {}) const = 0;
    virtual SettingsPreview preview_settings(const SettingsPatch& patch) const = 0;
    virtual CommandResult apply_settings(const SettingsPatch& patch, const std::vector<SettingChange>& expected,
                                         SettingsPreview& applied) = 0;
    // Every setting in force, for the All settings panel. Read-only, like
    // read_settings, and read fresh from Orca on every call.
    virtual SettingsCatalog settings_catalog() const = 0;

    // Directory for consumer-owned files that belong to the open project and
    // travel inside its saved archive. The path changes when the
    // authoritative project is replaced, so consumers must re-resolve it
    // after every Project change rather than caching it.
    virtual std::string auxiliary_data_dir() const = 0;

    // Writes the current authoritative project (model, plates, settings) to a
    // portable project archive at file_path, excluding auxiliary data — so a
    // clean copy carries no consumer files along.
    virtual CommandResult export_project_archive(const std::string& file_path) = 0;
    virtual ProjectDetails project_details() const = 0;

    // Seeing and exporting. `render_view` draws one plate offscreen;
    // `read_attachment` reads a file the project lists as an attachment;
    // `inspect_slice` reads a current slice; `check_export` refuses what
    // `export_file` would refuse, without writing; the cancels stop a run
    // and say whether they stopped it.
    virtual CommandResult render_view(const RenderRequest& request, RenderedImage& image) = 0;
    virtual CommandResult read_attachment(const std::string& id, AttachmentContent& content) const = 0;
    virtual SliceInspection inspect_slice(const SliceInspectRequest& request) const = 0;
    virtual CommandResult check_export(const ExportRequest& request) const = 0;
    virtual CommandResult export_file(const ExportRequest& request, ExportResult& result) = 0;
    virtual CommandResult cancel_slice(bool& stopped) = 0;
    virtual CommandResult cancel_job(const std::string& handle, bool& stopped) = 0;
    virtual CommandResult open_project(const ProjectOpenRequest& request, LoadReport& report) = 0;

    // Imports a model or project file's geometry into the CURRENT project,
    // adding objects rather than replacing the project. It is a single
    // undoable manufacturing change: the session is unchanged, prior IDs stay
    // valid, revision advances, and a Contents change is published. On success
    // object_id is the first added object (when one can be identified).
    virtual CommandResult import_objects(const ImportRequest& request, LoadReport& report,
                                         std::vector<ObjectId>& added) = 0;

    // Loads the person started themselves (Home, drag and drop, File menu),
    // reported once each has finished, a turn of the event loop later so the
    // project it opened is in place. Loads a tool started come back in that
    // tool's own report instead. One listener; an empty function removes it.
    virtual void set_load_report_listener(std::function<void(const LoadReport&)> listener) = 0;
    virtual CommandResult delete_items(const std::vector<DeleteItem>& items) = 0;

    // Reshaping. `preview_divide` works on a copy and changes nothing;
    // `divide_object`, `merge_objects` and `repair_object` are one undo step
    // each. A merge's result is the new object.
    virtual CommandResult preview_divide(ObjectId id, const DivideRequest& request, DivideResult& result) const = 0;
    virtual CommandResult divide_object(ObjectId id, const DivideRequest& request, DivideResult& result) = 0;
    virtual CommandResult merge_objects(const std::vector<ObjectId>& ids, ObjectId& merged) = 0;
